class QuestionApplication:
    __doc__ = "Application-side human question admission and observation. Server derives caller scope and text, preserves native Via evidence, and owns a versioned bounded Book. Operator answering/history use the separately authorized QuestionOperator service; this application service exposes no administrative secret or operator methods."
    def Ask(self, question: "ApplicationQuestion") -> "QuestionObservation":
        raise NotImplementedError
    def Observe(self, request_key: "str", wait_ms: "int") -> "QuestionObservation":
        raise NotImplementedError


class QuestionApplicationClient(QuestionApplication):
    def __init__(self, transport):
        self._transport = transport

    def Ask(self, question: "ApplicationQuestion") -> "QuestionObservation":
        _service_check("ApplicationQuestion", question)
        _oa_args = OAQuestionApplicationAskArguments()
        _oa_args.question = question
        _oa_arguments = _service_encode(enc_oaquestionapplicationaskarguments, _oa_args, 1)
        _service_decode(_decode_oaquestionapplicationaskarguments, _oa_arguments, 1)
        _oa_request = _service_request("abstraction.asks/application@1", "Ask", _oa_arguments)
        _oa_payload = _service_response(self._transport.exchange_frame(_oa_request), "abstraction.asks/application@1", "Ask")
        _oa_result = _service_decode(_decode_oaquestionapplicationaskresult, _oa_payload, 1)
        return _oa_result.value

    def Observe(self, request_key: "str", wait_ms: "int") -> "QuestionObservation":
        _service_check("string", request_key)
        _service_check("i64", wait_ms)
        _oa_args = OAQuestionApplicationObserveArguments()
        _oa_args.request_key = request_key
        _oa_args.wait_ms = wait_ms
        _oa_arguments = _service_encode(enc_oaquestionapplicationobservearguments, _oa_args, 1)
        _service_decode(_decode_oaquestionapplicationobservearguments, _oa_arguments, 1)
        _oa_request = _service_request("abstraction.asks/application@1", "Observe", _oa_arguments)
        _oa_payload = _service_response(self._transport.exchange_frame(_oa_request), "abstraction.asks/application@1", "Observe")
        _oa_result = _service_decode(_decode_oaquestionapplicationobserveresult, _oa_payload, 1)
        return _oa_result.value


